//! Oracle: `svelters_compiler::acorn::parse` against real acorn 8.19.0 (target/oracle/acorn.jsonl,
//! generated by tools/oracle/gen.mjs). See tests/oracle_common/mod.rs for the comparison rules.
//!
//! `cargo test -p svelters-compiler --release --test oracle_acorn -- --nocapture`

mod oracle_common;

use oracle_common::*;
use serde_json::{json, Value};
use svelters_compiler::acorn::{self, Options};
use svelters_compiler::estree::{self, SourceType};

/// acorn options the port models. Keys that only add `loc`/`range`/tokens or are callbacks that
/// never change the AST are accepted and ignored; anything else makes the case `skipped`.
fn map_options(o: &Value) -> Result<Options, String> {
    let mut opts = Options { ecma_version: 5, source_type: SourceType::Script, preserve_parens: false, allow_undefined_exports: false };
    for (k, v) in o.as_object().into_iter().flatten() {
        match k.as_str() {
            // acorn getOptions(): "latest" -> 1e8, years -> versions
            "ecmaVersion" => {
                opts.ecma_version = match v {
                    Value::String(s) if s == "latest" => 100_000_000,
                    Value::Number(n) => {
                        let n = n.as_u64().ok_or_else(|| format!("ecmaVersion {n}"))? as u32;
                        if n >= 2015 { n - 2009 } else { n }
                    }
                    _ => return Err(format!("ecmaVersion {v}")),
                }
            }
            "sourceType" => {
                opts.source_type = match v.as_str() {
                    Some("script") => SourceType::Script,
                    Some("module") => SourceType::Module,
                    _ => return Err(format!("sourceType {v}")),
                }
            }
            "preserveParens" => opts.preserve_parens = v.as_bool() == Some(true),
            "locations" | "ranges" | "sourceFile" | "onComment" | "onToken" | "onInsertedSemicolon" | "onTrailingComma" => {}
            // test-driver flags (acorn-loose / commonjs runs), not acorn options: acorn ignores them
            "loose" | "commonjs" => {}
            _ => return Err(format!("unsupported option {k}")),
        }
    }
    Ok(opts)
}

fn expected_ok(case: &Value) -> Value {
    let mut e = json!({ "ast": case["ast"], "comments": case["comments"] });
    normalize(&mut e, Suite::Acorn);
    e
}

/// Compares our successful parse (serialized, BYTE offsets) with the corpus.
fn compare_ok(case: &Value, mut ours: Value, map: &Utf16Map) -> Outcome {
    if !case["error"].is_null() {
        let e = &case["error"];
        return Outcome::ErrorMismatch(format!("expected error {:?} at {}, ours parsed", e["message"].as_str().unwrap_or(""), e["pos"]));
    }
    bytes_to_utf16(&mut ours, map);
    normalize(&mut ours, Suite::Acorn);
    match diff(&expected_ok(case), &ours) {
        None => Outcome::Pass,
        Some(d) => Outcome::AstMismatch(d),
    }
}

/// Compares our error (`pos` in BYTES) with the corpus.
fn compare_err(case: &Value, message: &str, pos: u64, map: &Utf16Map) -> Outcome {
    let e = &case["error"];
    if e.is_null() {
        return Outcome::ErrorMismatch(format!("expected AST, ours failed: {message:?} at byte {pos}"));
    }
    let ours_pos = map.convert(pos);
    let exp_msg = e["message"].as_str().unwrap_or("");
    if exp_msg == message && num_or_eq(&e["pos"], &ours_pos) {
        Outcome::Pass
    } else {
        Outcome::ErrorMismatch(format!("expected {exp_msg:?} at {}, ours {message:?} at {ours_pos}", e["pos"]))
    }
}

fn num_or_eq(a: &Value, b: &Value) -> bool {
    a == b || (a.as_f64().is_some() && a.as_f64() == b.as_f64())
}

fn precheck(case: &Value) -> Result<(&str, Options), Outcome> {
    if let Some(s) = case["skip"].as_str() {
        return Err(Outcome::Skipped(s.to_string()));
    }
    if case["error"]["crash"] == true {
        return Err(Outcome::Skipped("upstream threw a non-SyntaxError (option validation)".into()));
    }
    let opts = map_options(&case["options"]).map_err(Outcome::Skipped)?;
    Ok((case["code"].as_str().expect("case.code"), opts))
}

fn run_case(case: &Value) -> Outcome {
    let (code, opts) = match precheck(case) {
        Ok(x) => x,
        Err(o) => return o,
    };
    let map = Utf16Map::new(code);
    let r = guarded(|| {
        let mut comments: Vec<estree::Comment> = Vec::new();
        match acorn::parse(code, &opts, &mut comments) {
            Ok(program) => Ok(json!({
                "ast": serde_json::to_value(&program).expect("serialize Program"),
                "comments": serde_json::to_value(&comments).expect("serialize comments"),
            })),
            Err(e) => Err((e.message, e.pos as u64)),
        }
    });
    match r {
        Err(o) => o,
        Ok(Ok(ours)) => compare_ok(case, ours, &map),
        Ok(Err((msg, pos))) => compare_err(case, &msg, pos, &map),
    }
}

#[test]
fn oracle_acorn() {
    let Some(cases) = load_corpus("acorn") else { return };
    let cases = filter_cases(cases);
    let report = run_suite(Suite::Acorn, &cases, run_case);
    finish(&report);
}

// ---------------------------------------------------------------------------------------------
// self-tests of the harness (no parser needed)

/// Feeds every corpus expectation back through the "ours" path: offsets UTF-16 -> bytes, then
/// the same conversion + normalization + diff our parser's output goes through. Every case must
/// pass, which proves the offset conversion, the ignore list and the comparator are consistent.
#[test]
fn oracle_acorn_selftest_roundtrip() {
    let Some(cases) = load_corpus("acorn") else { return };
    let mut non_ascii = 0usize;
    let results = parallel_map(&cases, |case| {
        let (code, _) = match precheck(case) {
            Ok(x) => x,
            Err(_) => return (Outcome::Pass, false),
        };
        let map = Utf16Map::new(code);
        let back = ByteMap::new(code);
        let to_bytes = |u: u64| Value::from(back.to_byte(u).unwrap_or_else(|| panic!("{}: utf16 {u} inside a surrogate pair", case["id"])));
        let o = if case["error"].is_null() {
            let mut ours = json!({ "ast": case["ast"], "comments": case["comments"] });
            map_offsets(&mut ours, &to_bytes);
            compare_ok(case, ours, &map)
        } else {
            let pos = to_bytes(case["error"]["pos"].as_u64().unwrap()).as_u64().unwrap();
            compare_err(case, case["error"]["message"].as_str().unwrap(), pos, &map)
        };
        (o, !code.is_ascii())
    });
    let mut bad = Vec::new();
    for ((o, na), case) in results.iter().zip(&cases) {
        non_ascii += *na as usize;
        if !matches!(o, Outcome::Pass) {
            bad.push(format!("{}: {}", case["id"], o.detail()));
        }
    }
    println!("acorn self-test: {} cases round-tripped, {non_ascii} with non-ASCII source", cases.len());
    assert!(bad.is_empty(), "round trip failed for {} cases:\n{}", bad.len(), bad[..bad.len().min(20)].join("\n"));
    assert!(non_ascii > 10, "corpus should exercise non-ASCII sources");
}

#[test]
fn utf16_map_non_ascii() {
    // a=1 byte/1 unit, é=2/1, 😀=4/2, b=1/1
    let src = "aé😀b";
    let m = Utf16Map::new(src);
    let expect = [(0, Some(0)), (1, Some(1)), (2, None), (3, Some(2)), (4, None), (5, None), (6, None), (7, Some(4)), (8, Some(5)), (9, None)];
    for (b, u) in expect {
        assert_eq!(m.to_utf16(b), u, "byte {b}");
    }
    assert_eq!(m.convert(2), Value::String("<byte 2: not a char boundary>".into()));
    let back = ByteMap::new(src);
    for (u, b) in [(0, Some(0)), (1, Some(1)), (2, Some(3)), (3, None), (4, Some(7)), (5, Some(8)), (6, None)] {
        assert_eq!(back.to_byte(u), b, "utf16 {u}");
    }
}

#[test]
fn comparator_rules() {
    assert!(diff(&json!({"a": 1, "b": [1, 2]}), &json!({"b": [1.0, 2], "a": 1.0})).is_none(), "numbers by value, key order free");
    let d = diff(&json!({"type": "X", "a": {"b": [1, {"c": "x"}]}}), &json!({"type": "X", "a": {"b": [1, {"c": "y"}]}})).unwrap();
    assert_eq!(d.path, "<X>.a.b[1].c");
    let d = diff(&json!({"a": 1}), &json!({"a": 1, "b": null})).unwrap();
    assert_eq!((d.path.as_str(), d.expected.as_str()), ("b", "<absent>"), "absent != null");
    let d = diff(&json!({"a": [1]}), &json!({"a": [1, 2]})).unwrap();
    assert_eq!(d.path, "a.length");
    assert!(diff(&json!("1"), &json!(1)).is_some());
    assert!(diff(&json!(true), &json!(1)).is_some());
    // ignore list
    let mut e = json!({"type": "Literal", "start": 0, "end": 4, "loc": {"start": {"line": 1}}, "value": {}, "raw": "/a/g", "regex": {"pattern": "a", "flags": "g"}});
    let mut o = json!({"type": "Literal", "start": 0, "end": 4, "value": null, "raw": "/a/g", "regex": {"pattern": "a", "flags": "g"}});
    normalize(&mut e, Suite::Acorn);
    normalize(&mut o, Suite::Acorn);
    assert!(diff(&e, &o).is_none());
    // svelte-only ignores do not apply to acorn
    let mut e = json!({"type": "Identifier", "name": "x", "metadata": {}});
    normalize(&mut e, Suite::Acorn);
    assert!(e.get("metadata").is_some());
}

/// The real `estree` serde output of a hand-built AST, after byte -> UTF-16 conversion, equals
/// real acorn's JSON for the same non-ASCII source (captured from acorn 8.19.0, ecmaVersion 16).
#[test]
fn estree_contract_smoke() {
    use estree::*;
    let src = "é; 1 /* 😀 */\n";
    let acorn_json = json!({
        "ast": {"type":"Program","start":0,"end":14,"body":[
            {"type":"ExpressionStatement","start":0,"end":2,"expression":{"type":"Identifier","start":0,"end":1,"name":"é"}},
            {"type":"ExpressionStatement","start":3,"end":4,"expression":{"type":"Literal","start":3,"end":4,"value":1,"raw":"1"}}],
            "sourceType":"script"},
        "comments": [{"type":"Block","value":" 😀 ","start":5,"end":13}]
    });
    let program = Program {
        start: 0,
        end: 17,
        body: vec![
            Statement::ExpressionStatement(ExpressionStatement {
                start: 0,
                end: 3,
                expression: Expression::Identifier(Identifier { start: 0, end: 2, name: "é".into() }),
                directive: None,
            }),
            Statement::ExpressionStatement(ExpressionStatement {
                start: 4,
                end: 5,
                expression: Expression::Literal(Literal { start: 4, end: 5, value: LiteralValue::Number(1.0), raw: "1".into(), regex: None, bigint: None }),
                directive: None,
            }),
        ],
        source_type: SourceType::Script,
    };
    let comments = vec![Comment { kind: CommentKind::Block, value: " 😀 ".into(), start: 6, end: 16 }];
    let case = json!({ "ast": acorn_json["ast"], "comments": acorn_json["comments"], "error": null });
    let ours = json!({ "ast": serde_json::to_value(&program).unwrap(), "comments": serde_json::to_value(&comments).unwrap() });
    let o = compare_ok(&case, ours.clone(), &Utf16Map::new(src));
    assert!(matches!(o, Outcome::Pass), "{}", o.detail());
    // and an off-by-one byte offset is caught
    let mut wrong = ours;
    wrong["ast"]["body"][0]["expression"]["end"] = json!(1);
    let o = compare_ok(&case, wrong, &Utf16Map::new(src));
    assert!(matches!(&o, Outcome::AstMismatch(d) if d.path == "ast<Program>.body[0]<ExpressionStatement>.expression<Identifier>.end"), "{}", o.detail());
}

#[test]
fn guarded_classifies_panics() {
    assert!(matches!(guarded(|| -> u32 { todo!("agent A") }), Err(Outcome::Unimplemented(_))));
    assert!(matches!(guarded(|| -> u32 { panic!("boom") }), Err(Outcome::Panicked(m)) if m == "boom"));
    assert!(matches!(guarded(|| 7), Ok(7)));
}
